1	package batchreg
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"strconv"
9		"unicode/utf8"
10	)
11	
12	// This file holds the single-record rules shared by the two on-disk sources:
13	// the registry file (decode, where stored text is already authoritative) and
14	// an import manifest (ParseManifest, where text is normalized on the way in).
15	// Both sources accept exactly the same four lowercase fields with the same
16	// strict JSON decoding — case-sensitive names, escaped spellings counted,
17	// duplicates visible, strict UTF-8 and strict JSON-integer quantities. The
18	// source-specific differences live in the callers:
19	//
20	//   - text policy: registry records are read verbatim (an empty string is a
21	//     format-level problem handled later by validate), while manifest text is
22	//     trimmed and must stay non-empty;
23	//   - which problem is reported first when one object has several: registry
24	//     records reject any duplicated field before an unknown one, manifest
25	//     records reject whichever anomaly appears first in source order;
26	//   - error types and reason wording, which remain owned by each caller.
27	type textPolicy int
28	
29	const (
30		textVerbatim textPolicy = iota // registry record: decode, keep as written
31		textTrimmed                    // manifest record: trim ends, reject blank
32	)
33	
34	// keyEncodingReason is the shared reason sentence for a member NAME that
35	// cannot be decoded (malformed UTF-8 bytes or a lone surrogate escape in the
36	// JSON string source). It is deliberately distinct from the two neighboring
37	// causes: a field VALUE with bad encoding ("must be valid UTF-8 text" /
38	// *EncodingError, naming the field) and a record that is not an object at
39	// all ("record must be a JSON object"). The offending bytes are never
40	// echoed: decoding them would substitute U+FFFD and make distinct names
41	// collide, and the substituted text must never be mistaken for a real name.
42	const keyEncodingReason = "a field name contains bytes that are not valid UTF-8 or holds a lone surrogate escape; the name is rejected instead of being replaced with U+FFFD"
43	
44	// unambiguousBatchID returns the record's batch id only when it can be
45	// determined uniquely and reliably: exactly one "batch" member (counted after
46	// JSON key decoding, so an escaped respelling is the same member) holding one
47	// JSON string whose decoded text is valid UTF-8 and, under textTrimmed,
48	// non-blank after trimming. A missing, duplicated, mistyped, malformed or
49	// blank member yields "" — never a U+FFFD substitution and never one of two
50	// repeated values picked arbitrarily. The trimmed policy returns the
51	// normalized id; the verbatim policy returns the decoded text untouched.
52	func unambiguousBatchID(fields []objectField, policy textPolicy) string {
53		if countField(fields, "batch") != 1 {
54			return ""
55		}
56		raw, ok := findField(fields, "batch")
57		if !ok {
58			return ""
59		}
60		id, err := unmarshalStringStrict(raw)
61		if err != nil {
62			return ""
63		}
64		if policy == textTrimmed {
65			normalized, err := NormalizeField(id)
66			if err != nil {
67				return ""
68			}
69			id = normalized
70		}
71		return id
72	}
73	
74	// memberFault identifies one structural problem with an object's field names.
75	type memberFaultKind int
76	
77	const (
78		faultNone memberFaultKind = iota
79		faultDuplicate
80		faultUnknown
81	)
82	
83	type memberFault struct {
84		field string
85		kind  memberFaultKind
86	}
87	
88	// checkRecordMembers validates the member names of one batch record against
89	// batchRecordFields. With duplicatesFirst it reports the first member name
90	// that repeats anywhere in the object, and only reports an unknown member
91	// when nothing is repeated — the registry file rule. Otherwise it reports
92	// the first anomaly encountered in source order, be it an unknown member or
93	// a repeat — the manifest rule. In source order, an unknown name outranks a
94	// repeat on the same member, matching the original per-member scan. Repeated
95	// keys are detected on the decoded name, so a field hidden behind a JSON
96	// escape is the same member.
97	func checkRecordMembers(fields []objectField, duplicatesFirst bool) memberFault {
98		seen := make(map[string]struct{}, len(fields))
99		var firstDuplicate, firstUnknown memberFault
100		for _, f := range fields {
101			_, known := batchRecordFields[f.key]
102			_, repeated := seen[f.key]
103			seen[f.key] = struct{}{}
104			if !duplicatesFirst {
105				if !known {
106					return memberFault{field: f.key, kind: faultUnknown}
107				}
108				if repeated {
109					return memberFault{field: f.key, kind: faultDuplicate}
110				}
111				continue
112			}
113			if repeated && firstDuplicate.kind == faultNone {
114				firstDuplicate = memberFault{field: f.key, kind: faultDuplicate}
115			}
116			if !known && firstUnknown.kind == faultNone {
117				firstUnknown = memberFault{field: f.key, kind: faultUnknown}
118			}
119		}
120		if duplicatesFirst {
121			if firstDuplicate.kind != faultNone {
122				return firstDuplicate
123			}
124			return firstUnknown
125		}
126		return memberFault{}
127	}
128	
129	// fieldProblem classifies what is wrong with one text member's value,
130	// independently of the error wording each source presents.
131	type fieldProblem int
132	
133	const (
134		fieldOK fieldProblem = iota
135		fieldMissing
136		fieldNotString
137		fieldEncoding
138		fieldBlank
139	)
140	
141	// decodeRecordText reads one text member. found says whether the member
142	// exists; raw is its JSON value. Under textVerbatim every syntactically and
143	// encoding-valid string is returned as written, including "". Under
144	// textTrimmed the value must additionally be non-empty after trimming
145	// (NormalizeField); in that case cause carries NormalizeField's error so the
146	// caller can keep the established reason wording.
147	func decodeRecordText(raw json.RawMessage, found bool, policy textPolicy) (value string, problem fieldProblem, cause error) {
148		if !found {
149			return "", fieldMissing, nil
150		}
151		if trimmed := bytes.TrimSpace(raw); len(trimmed) == 0 || trimmed[0] != '"' {
152			return "", fieldNotString, nil
153		}
154		value, err := unmarshalStringStrict(raw)
155		if errors.Is(err, errStringEncoding) {
156			return "", fieldEncoding, nil
157		}
158		if err != nil {
159			return "", fieldNotString, nil
160		}
161		if policy == textTrimmed {
162			normalized, normErr := NormalizeField(value)
163			if normErr != nil {
164				// After strict decoding the only remaining failure is a blank
165				// result, but keep the cause rather than re-stating its text.
166				return "", fieldBlank, normErr
167			}
168			value = normalized
169		}
170		return value, fieldOK, nil
171	}
172	
173	// quantityShape classifies a JSON quantity token without assigning source-
174	// specific wording. The token is the trimmed raw JSON value; the callers
175	// decide how each class is phrased for registry files versus manifests.
176	type quantityShape int
177	
178	const (
179		qtyValid       quantityShape = iota
180		qtyNotNumeric                // value does not even start as a JSON number digit
181		qtyFractional                // digits followed by '.', 'e' or another non-digit
182		qtyLeadingZero               // "01": no conforming JSON document can reach this
183		qtyOutOfRange                // all digits, but outside signed 64-bit range
184		qtyZero
185	)
186	
187	// classifyJSONQuantity is the shared numeric rule: a strict JSON integer
188	// token (no sign, fraction or exponent) in 1..MaxQuantity. It only inspects
189	// token shape and range — never the surrounding object — so both on-disk
190	// sources and every future caller maintain one quantity definition.
191	func classifyJSONQuantity(token []byte) (int64, quantityShape) {
192		if len(token) == 0 || token[0] < '0' || token[0] > '9' {
193			return 0, qtyNotNumeric
194		}
195		for _, c := range token {
196			if c < '0' || c > '9' {
197				return 0, qtyFractional
198			}
199		}
200		if len(token) > 1 && token[0] == '0' {
201			return 0, qtyLeadingZero
202		}
203		value, err := strconv.ParseInt(string(token), 10, 64)
204		if err != nil {
205			return 0, qtyOutOfRange
206		}
207		if value == 0 {
208			return 0, qtyZero
209		}
210		return value, qtyValid
211	}
212	
213	// recordTextField is one of the three textual members every record carries.
214	type recordTextField struct {
215		name  string
216		value string
217	}
218	
219	// recordTextFields lists batch, product and unit in the fixed order in which
220	// per-field problems are reported, so every validation entry point iterates
221	// the same three members.
222	func recordTextFields(batch, product, unit string) []recordTextField {
223		return []recordTextField{
224			{"batch", batch},
225			{"product", product},
226			{"unit", unit},
227		}
228	}
229	
230	// safeBatchIDForError returns id exactly when it may be cited in an error:
231	// non-empty and valid UTF-8. An empty or malformed id yields "" so no value
232	// and no U+FFFD substitution is ever invented to name a batch.
233	func safeBatchIDForError(id string) string {
234		if id != "" && utf8.ValidString(id) {
235			return id
236		}
237		return ""
238	}
239	
240	// textIssueKind classifies one problem with an already-decoded text field.
241	type textIssueKind int
242	
243	const (
244		textEmpty    textIssueKind = iota // the empty string; whitespace-only text is not empty
245		textEncoding                      // the bytes are not valid UTF-8
246	)
247	
248	// textIssue is one problem with one text field of an already-decoded record.
249	type textIssue struct {
250		field string // "batch", "product" or "unit"
251		kind  textIssueKind
252	}
253	
254	// inspectRecordText examines the three text fields of an already-decoded
255	// record and lists every problem found, in the fixed batch, product, unit
256	// field order with a field's encoding problem listed before its empty-string
257	// problem. Text is checked verbatim — no trimming, no case folding — so
258	// whitespace-only text counts as ordinary non-empty text. This is the single
259	// definition of the text rules for the three entry points that validate
260	// decoded records (Register, Import and Save); each of them picks which issue
261	// to report first according to its own documented ordering.
262	func inspectRecordText(batch, product, unit string) []textIssue {
263		var issues []textIssue
264		for _, tv := range recordTextFields(batch, product, unit) {
265			if !utf8.ValidString(tv.value) {
266				issues = append(issues, textIssue{field: tv.name, kind: textEncoding})
267			}
268			if tv.value == "" {
269				issues = append(issues, textIssue{field: tv.name, kind: textEmpty})
270			}
271		}
272		return issues
273	}
274	
275	// firstTextIssue returns the first issue of the given kind, if any.
276	func firstTextIssue(issues []textIssue, kind textIssueKind) (textIssue, bool) {
277		for _, issue := range issues {
278			if issue.kind == kind {
279				return issue, true
280			}
281		}
282		return textIssue{}, false
283	}
284	
285	// decodedQuantityProblem classifies an already-decoded quantity against the
286	// accepted 1..MaxQuantity window shared by every entry point.
287	type decodedQuantityProblem int
288	
289	const (
290		decodedQtyOK decodedQuantityProblem = iota
291		decodedQtyNotPositive
292		decodedQtyAboveMax
293	)
294	
295	// classifyDecodedQuantity is the single quantity rule for already-decoded
296	// records; the callers decide how each class is phrased.
297	func classifyDecodedQuantity(quantity int64) decodedQuantityProblem {
298		switch {
299		case quantity <= 0:
300			return decodedQtyNotPositive
301		case quantity > MaxQuantity:
302			return decodedQtyAboveMax
303		default:
304			return decodedQtyOK
305		}
306	}
307	
308	// quantityInRange reports whether an already-decoded quantity lies in the
309	// accepted 1..MaxQuantity window shared by every entry point.
310	func quantityInRange(quantity int64) bool {
311		return classifyDecodedQuantity(quantity) == decodedQtyOK
312	}
313	
314	// These wrappers keep the registry-specific reason strings next to the
315	// registry parser while sharing classifyJSONQuantity; the wording predates
316	// the shared classifier and must not change.
317	func registryQuantityError(token []byte) (int64, error) {
318		value, shape := classifyJSONQuantity(token)
319		switch shape {
320		case qtyValid:
321			return value, nil
322		case qtyZero:
323			return 0, errors.New("must be greater than zero")
324		case qtyOutOfRange:
325			return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
326		case qtyLeadingZero:
327			// No conforming JSON token reaches this branch (leading zeros fail the
328			// document scan); historically such a digit run was parsed on its
329			// numeric value, so keep that exact behavior.
330			parsed, err := strconv.ParseInt(string(token), 10, 64)
331			if err != nil {
332				return 0, fmt.Errorf("must be an integer no greater than %d", MaxQuantity)
333			}
334			if parsed == 0 {
335				return 0, errors.New("must be greater than zero")
336			}
337			return parsed, nil
338		default: // qtyNotNumeric, qtyFractional
339			return 0, fmt.Errorf("must be a JSON integer between 1 and %d", MaxQuantity)
340		}
341	}
342	
343	// manifestQuantityError mirrors the manifest wording: non-numeric values and
344	// signed numbers point at the accepted range, while fractions, exponents and
345	// (defensively) leading zeros each keep their own sentence.
346	func manifestQuantityError(token []byte) (int64, error) {
347		value, shape := classifyJSONQuantity(token)
348		switch shape {
349		case qtyValid:
350			return value, nil
351		case qtyZero:
352			return 0, errors.New(`field "quantity" must be greater than zero`)
353		case qtyLeadingZero:
354			return 0, errors.New(`field "quantity" must be a JSON integer without leading zeros`)
355		case qtyFractional:
356			return 0, errors.New(`field "quantity" must be a JSON integer without sign, fraction or exponent`)
357		case qtyOutOfRange:
358			return 0, fmt.Errorf(`field %q must be an integer no greater than %d`, "quantity", MaxQuantity)
359		default: // qtyNotNumeric
360			return 0, fmt.Errorf(`field %q must be a JSON integer between 1 and %d`, "quantity", MaxQuantity)
361		}
362	}
