178	func runBatchRegister(args []string, stdout io.Writer) error {
179		fs := flag.NewFlagSet("batch-register", flag.ContinueOnError)
180		fs.SetOutput(io.Discard)
181		registryPath := fs.String("registry", "", "registry `file` to read and write")
182		batchRaw := fs.String("batch", "", "batch number (unique within the registry)")
183		productRaw := fs.String("product", "", "product number")
184		quantityRaw := fs.String("quantity", "", "positive decimal integer quantity")
185		unitRaw := fs.String("unit", "", "measurement unit")
186		if err := fs.Parse(args); err != nil {
187			if errors.Is(err, flag.ErrHelp) {
188				fmt.Fprint(stdout, rootUsage())
189				return nil
190			}
191			return &usageError{msg: "batch-register: " + err.Error(), usage: batchRegisterUsage}
192		}
193		if fs.NArg() != 0 {
194			return &usageError{
195				msg:   fmt.Sprintf("batch-register: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
196				usage: batchRegisterUsage,
197			}
198		}
199	
200		// Missing or malformed input must never create or modify the registry
201		// file, so required flags are checked before reading or writing anything.
202		required := []struct {
203			name  string
204			value string
205		}{
206			{"--registry", *registryPath},
207			{"--batch", *batchRaw},
208			{"--product", *productRaw},
209			{"--quantity", *quantityRaw},
210			{"--unit", *unitRaw},
211		}
212		var missing []string
213		for _, f := range required {
214			if f.value == "" {
215				missing = append(missing, f.name)
216			}
217		}
218		if len(missing) > 0 {
219			return &usageError{
220				msg:   "batch-register: missing required flag(s): " + strings.Join(missing, ", "),
221				usage: batchRegisterUsage,
222			}
223		}
224	
225		batch, err := batchreg.NormalizeField(*batchRaw)
226		if err != nil {
227			return &usageError{msg: "batch-register: invalid --batch: " + err.Error(), usage: batchRegisterUsage}
228		}
229		product, err := batchreg.NormalizeField(*productRaw)
230		if err != nil {
231			return &usageError{msg: "batch-register: invalid --product: " + err.Error(), usage: batchRegisterUsage}
232		}
233		unit, err := batchreg.NormalizeField(*unitRaw)
234		if err != nil {
235			return &usageError{msg: "batch-register: invalid --unit: " + err.Error(), usage: batchRegisterUsage}
236		}
237		quantity, err := batchreg.ParseQuantity(*quantityRaw)
238		if err != nil {
239			return &usageError{msg: "batch-register: invalid --quantity: " + err.Error(), usage: batchRegisterUsage}
240		}
241	
242		reg, existed, err := batchreg.Load(*registryPath)
243		if err != nil {
244			return err
245		}
246		outcome, err := batchreg.Register(reg, batchreg.Input{
247			Batch: batch, Product: product, Quantity: quantity, Unit: unit,
248		})
249		if err != nil {
250			return err
251		}
252		if outcome.Created {
253			if err := batchreg.Save(*registryPath, reg); err != nil {
254				if !existed {
255					// Nothing was registered before; drop any partial new file.
256					removePartialNewRegistry(*registryPath)
257				}
258				return err
259			}
260		}
261	
262		status := "duplicate"
263		if outcome.Created {
264			status = "created"
265		}
266		result := struct {
267			Batch    string `json:"batch"`
268			Product  string `json:"product"`
269			Quantity int64  `json:"quantity"`
270			Unit     string `json:"unit"`
271			Status   string `json:"status"`
272		}{
273			Batch:    outcome.Batch.Batch,
274			Product:  outcome.Batch.Product,
275			Quantity: outcome.Batch.Quantity,
276			Unit:     outcome.Batch.Unit,
277			Status:   status,
278		}
279		payload, err := json.Marshal(result)
280		if err != nil {
281			return err
282		}
283		_, err = fmt.Fprintln(stdout, string(payload))
284		return err
285	}
286	
287	func runBatchImport(args []string, stdout io.Writer) error {
288		fs := flag.NewFlagSet("batch-import", flag.ContinueOnError)
289		fs.SetOutput(io.Discard)
290		registryPath := fs.String("registry", "", "registry `file` to read and write")
291		inputPath := fs.String("input", "", "read-only JSON manifest `file` to import")
292		if err := fs.Parse(args); err != nil {
293			if errors.Is(err, flag.ErrHelp) {
294				fmt.Fprint(stdout, rootUsage())
295				return nil
296			}
297			return &usageError{msg: "batch-import: " + err.Error(), usage: batchImportUsage}
298		}
299		if fs.NArg() != 0 {
300			return &usageError{
301				msg:   fmt.Sprintf("batch-import: unexpected positional argument(s): %s", strings.Join(fs.Args(), " ")),
302				usage: batchImportUsage,
303			}
304		}
305		if *registryPath == "" || *inputPath == "" {
306			var missing []string
307			if *registryPath == "" {
308				missing = append(missing, "--registry")
309			}
310			if *inputPath == "" {
311				missing = append(missing, "--input")
312			}
313			return &usageError{
314				msg:   "batch-import: missing required flag(s): " + strings.Join(missing, ", "),
315				usage: batchImportUsage,
316			}
317		}
318	
319		// The manifest is read-only and is parsed (and fully validated) before
320		// the registry is loaded or written, so bad input cannot touch it.
321		data, err := os.ReadFile(*inputPath)
322		if err != nil {
323			return fmt.Errorf("batch-import: cannot read input file %q: %w", *inputPath, err)
324		}
325		inputs, err := batchreg.ParseManifest(data)
326		if err != nil {
327			return fmt.Errorf("batch-import: invalid input file %q: %w", *inputPath, err)
328		}
329	
330		reg, existed, err := batchreg.Load(*registryPath)
331		if err != nil {
332			return fmt.Errorf("batch-import: %w", err)
333		}
334		outcomes, err := batchreg.Import(reg, inputs)
335		if err != nil {
336			return fmt.Errorf("batch-import: %w", err)
337		}
338	
339		type importResultJSON struct {
340			Batch    string `json:"batch"`
341			Product  string `json:"product"`
342			Quantity int64  `json:"quantity"`
343			Unit     string `json:"unit"`
344			Status   string `json:"status"`
345		}
346		results := make([]importResultJSON, len(outcomes))
347		anyCreated := false
348		for i, o := range outcomes {
349			status := "duplicate"
350			if o.Created {
351				status = "created"
352				anyCreated = true
353			}
354			results[i] = importResultJSON{
355				Batch:    o.Batch.Batch,
356				Product:  o.Batch.Product,
357				Quantity: o.Batch.Quantity,
358				Unit:     o.Batch.Unit,
359				Status:   status,
360			}
361		}
362	
363		// An all-duplicate manifest must leave bytes and mtime untouched, so the
364		// registry is written only when at least one record was newly created.
365		if anyCreated {
366			if err := batchreg.Save(*registryPath, reg); err != nil {
367				if !existed {
368					// The registry never existed before this import; drop any
369					// partial new file so a failed save leaves nothing behind.
370					removePartialNewRegistry(*registryPath)
371				}
372				return fmt.Errorf("batch-import: %w", err)
373			}
374		}
375	
376		payload, err := json.Marshal(struct {
377			Results []importResultJSON `json:"results"`
378		}{Results: results})
379		if err != nil {
380			return fmt.Errorf("batch-import: %w", err)
381		}
382		_, err = fmt.Fprintln(stdout, string(payload))
383		if err != nil {
384			return fmt.Errorf("batch-import: %w", err)
385		}
386		return nil
387	}
388	
389	// removePartialNewRegistry drops a partially written new registry file after
390	// a failed first save. A symbolic link is never removed: the link is the
391	// user's pointer to the real registry file, not a partial creation of this
392	// run.
393	func removePartialNewRegistry(path string) {
394		info, err := os.Lstat(path)
395		if err != nil || info.Mode()&os.ModeSymlink != 0 {
396			return
397		}
398		os.Remove(path)
399	}
400	
401	func runDemo() {
402		proposal := govflow.Proposal{ID: "gip-7", Title: "fund the audit workstream", State: "voting", Quorum: 1000,
403			TimelockEnd: 5000, Actions: []string{"transfer:audits:25000"}}
404		if err := govflow.Vote(&proposal, 700, true); err != nil {
405			fmt.Println("vote refused:", err)
406		}
407		if err := govflow.Vote(&proposal, 200, false); err != nil {
408			fmt.Println("vote refused:", err)
409		}
410		next := govflow.Tally(&proposal)
411		fmt.Printf("proposal=%s for=%d against=%d quorum=%d next=%s\n", proposal.ID, proposal.ForVotes, proposal.AgainstVotes, proposal.Quorum, next)
412		proposal.State = next
413		proposal.TimelockEnd = 400
414		fmt.Println("executable now:", govflow.Executable([]govflow.Proposal{proposal}, 1000))
415	}
