315	// the injected rename test above.
316	func TestSaveThroughDirectorySymlinkDotDotFailsWhenRealDirectoryUnwritable(t *testing.T) {
317		if os.Geteuid() == 0 {
318			t.Skip("root bypasses directory write permission bits")
319		}
320		root, userPath, realPath, decoyPath, aliasPath, original := dirLinkFixture(t, filepath.Join("..", "store", "child"))
321		storeDir := filepath.Join(root, "store")
322		pinned := pinFile(t, realPath)
