329		}
330		t.Cleanup(func() { _ = os.Chmod(storeDir, 0o755) })
331	
332		reg := mustLoad(t, userPath)
333		if _, err := Register(reg, Input{Batch: "NEW-1", Product: "P-9", Quantity: 5, Unit: "box"}); err != nil {
334			t.Fatal(err)
335		}
336		err = Save(userPath, reg)
337		if err == nil {
338			t.Fatal("a save into an unwritable real target directory must fail")
339		}
340		msg := err.Error()
341		if !strings.Contains(msg, userPath) {
342			t.Errorf("error %q must name the user-supplied registry path %q", msg, userPath)
343		}
344		if !strings.Contains(msg, "permission denied") {
