346		}
347		if info, err := os.Stat(realPath); err != nil {
348			t.Fatal(err)
349		} else if !info.ModTime().Equal(pinned) {
350			t.Fatalf("failed save moved the real registry mtime: got %v want %v", info.ModTime(), pinned)
351		}
352		after, err := os.ReadFile(realPath)
353		if err != nil {
354			t.Fatal(err)
355		}
356		if !bytes.Equal(after, original) {
