14	// This file is the regression net for Save when the caller supplies the whole
15	// registry table directly, rather than building it through Register or
16	// Import. The rule under guard: a save that succeeds must read back through
17	// Load exactly as supplied, while a rejected save behaves as if it never ran —
18	// the target file's bytes and modification time stay untouched (or the file is
19	// never created), no temporary file remains, and the caller's records and
20	// their order are unchanged.
21	func saveBatch(batch, product string, quantity int64, unit string) Batch {
22		return Batch{Batch: batch, Product: product, Quantity: quantity, Unit: unit}
23	}
24	
25	func assertBatchesEqual(t *testing.T, got, want []Batch) {
26		t.Helper()
27		if len(got) != len(want) {
28			t.Fatalf("got %d records, want %d: %+v", len(got), len(want), got)
29		}
30		for i := range want {
31			if got[i] != want[i] {
32				t.Errorf("record %d = %+v, want %+v", i+1, got[i], want[i])
33			}
34		}
35	}
