37	// assertNoLeftoverTempFiles walks root and fails if any save temp file
38	// (".govflow-registry-*.tmp") survived a rejected save.
39	func assertNoLeftoverTempFiles(t *testing.T, root string) {
40		t.Helper()
41		err := filepath.WalkDir(root, func(path string, d os.DirEntry, err error) error {
42			if err != nil || d.IsDir() {
43				return nil
44			}
45			if strings.HasPrefix(d.Name(), ".govflow-registry-") {
46				t.Errorf("rejected save left a temporary file behind: %s", path)
47			}
48			return nil
49		})
50		if err != nil {
51			t.Fatal(err)
52		}
53	}
