100	// On success the records read back in submission order with all four fields
101	// intact: quantity bounds, legal Chinese, a genuine U+FFFD the caller typed,
102	// and whitespace of every kind kept verbatim.
103	func TestSaveRoundTripPreservesOrderAndFields(t *testing.T) {
104		fffd := string(rune(0xFFFD))
105		want := []Batch{
106			// Leading/trailing whitespace and legal Chinese stay verbatim;
107			// quantity at the inclusive lower bound.
108			saveBatch(" B-1 ", " 产品 A ", 1, " 千克 "),
109			// Interior whitespace is part of each text value.
110			saveBatch("B 2", "P  7", 7, "b o x"),
111			// Whitespace-only non-empty text; quantity at the inclusive upper bound.
112			saveBatch(" ", "\t", MaxQuantity, "\n"),
113			// A replacement character the caller genuinely entered is ordinary text.
114			saveBatch("批次-"+fffd, "P"+fffd+"Q", 42, fffd),
115		}
116		path := filepath.Join(t.TempDir(), "registry.json")
117		reg := &Registry{Version: FormatVersion, Batches: append([]Batch(nil), want...)}
118		if err := Save(path, reg); err != nil {
119			t.Fatal(err)
120		}
121		data, err := os.ReadFile(path)
122		if err != nil {
123			t.Fatal(err)
124		}
125		// The genuine U+FFFD is written as its real UTF-8 bytes, never stripped
126		// or re-encoded as an escape.
127		if !bytes.Contains(data, []byte{0xEF, 0xBF, 0xBD}) {
128			t.Fatalf("saved file lost the genuine U+FFFD: %s", data)
129		}
130	
131		got, existed, err := Load(path)
132		if err != nil || !existed {
133			t.Fatalf("saved registry must read back: existed=%v err=%v", existed, err)
134		}
135		if got.Version != FormatVersion {
136			t.Fatalf("read-back version = %d, want %d", got.Version, FormatVersion)
137		}
138		assertBatchesEqual(t, got.Batches, want)
139		// The caller's own records survive the save unchanged and in order.
140		assertBatchesEqual(t, reg.Batches, want)
141	}
