197					path,
198					fmt.Sprintf("batches record %d", tc.pos),
199					strconv.Quote(tc.field),
200					tc.reason,
201				} {
202					if !strings.Contains(msg, want) {
203						t.Errorf("error %q must mention %q", msg, want)
204					}
205				}
206				if tc.batch == "" {
207					if strings.Contains(msg, "(batch \"") {
208						t.Errorf("error must not invent a batch id: %q", msg)
209					}
210				} else if !strings.Contains(msg, "(batch "+strconv.Quote(tc.batch)+")") {
211					t.Errorf("error must cite batch %q verbatim: %q", tc.batch, msg)
212				}
