400	// When the target already exists, any rejected save (invalid record, bad
401	// encoding or duplicate id) leaves its bytes and modification time exactly as
402	// they were; the old registry still loads with its original record.
403	func TestSaveRejectionKeepsExistingFileUnchanged(t *testing.T) {
404		const oldContent = `{"version":1,"batches":[{"batch":"OLD","product":"P","quantity":5,"unit":"kg"}]}`
